import {
  createReporter,
  readFile,
} from "./governance-common.mjs";

const reporter = createReporter("No scan-generated AGENTS validator");
const rootAgents = readFile("AGENTS.md");

reporter.assert(
  !rootAgents.startsWith("<!-- GENERATED BY scripts/generate-repository-intelligence.mjs"),
  "Root AGENTS.md must not be generated by repository intelligence scans",
);

reporter.assert(
  rootAgents.includes("HAND-AUTHORED LAW. NOT GENERATED."),
  "Root AGENTS.md must identify itself as hand-authored AGENTS_V2 law",
);

reporter.finish("root AGENTS.md is hand-authored");
